import type { Metadata, Viewport } from "next";
import { preload } from "react-dom";
import "./fonts.css";
import "./globals.css";
import { JsonLd } from "@/components/seo/JsonLd";
import { organizationSchema, websiteSchema } from "@/lib/seo/structured-data";

// Self-hosted subsets of Geist, Geist Mono and Newsreader, generated by
// scripts/fonts/subset.py (see scripts/fonts/README.md). Only the small core
// files are preloaded; the extended files sit behind unicode-range and
// download only on pages that use one of their characters.
const FONT_PRELOADS = [
  "/fonts/geist-core.5a712cb0.woff2",
  "/fonts/geist-mono-core.4f46e459.woff2",
  "/fonts/newsreader-core.4c4d8006.woff2",
];

const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL ?? "https://app-friends-web-production.ian-b42.workers.dev";

const description =
  "App Friends is the cross-promotion network and SDK for app developers. Trade installs with apps that aren't your competition — for free, or for hire.";

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: {
    default: "App Friends — Trade installs with apps that aren't your competition.",
    template: "%s · App Friends",
  },
  description,
  applicationName: "App Friends",
  category: "developer tools",
  alternates: { canonical: "/" },
  openGraph: {
    type: "website",
    siteName: "App Friends",
    title: "App Friends — Trade installs with apps that aren't your competition.",
    description,
    url: SITE_URL,
    locale: "en_US",
  },
  twitter: {
    card: "summary_large_image",
    title: "App Friends",
    description,
    site: "@appfriends",
    creator: "@appfriends",
  },
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large" },
  },
};

export const viewport: Viewport = {
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#FBFAFF" },
    { media: "(prefers-color-scheme: dark)", color: "#0E0B1A" },
  ],
  width: "device-width",
  initialScale: 1,
};

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  for (const href of FONT_PRELOADS) preload(href, { as: "font", type: "font/woff2", crossOrigin: "anonymous" });
  return (
    <html
      lang="en"
      className="fonts h-full antialiased"
    >
      <body className="min-h-full flex flex-col">
        <a href="#main" className="skip-to-content">
          Skip to content
        </a>
        <JsonLd data={[organizationSchema(), websiteSchema()]} />
        <div id="main" className="contents">
          {children}
        </div>
      </body>
    </html>
  );
}
